// DOM도 트리! 조건에 맞는 가장 가까운 노드를 BFS로 찾기
function findNearest(root, predicate) {
  const queue = [root];
  let head = 0;                          // shift() 대신 포인터로 O(1)
  while (head < queue.length) {
    const node = queue[head++];
    if (predicate(node)) return node;
    queue.push(...node.children);
  }
  return null;
}

