from collections import deque

def bfs_distance(graph, start):
    dist = {start: 0}                  # 방문 체크 겸 거리 기록
    q = deque([start])
    while q:
        node = q.popleft()             # 큐: 먼저 넣은 것부터, O(1)
        for nxt in graph[node]:
            if nxt not in dist:
                dist[nxt] = dist[node] + 1
                q.append(nxt)
    return dist

